from dataclasses import dataclass, asdict
import json


class LibraryError(Exception):
    pass


class NotAvailable(LibraryError):
    pass


@dataclass
class Book:
    title: str
    copies: int


class Library:
    def __init__(self):
        self._books = {}

    def add(self, title, copies):
        key = title.strip().lower()
        if key in self._books:
            self._books[key].copies += copies
        else:
            self._books[key] = Book(key, copies)

    def lend(self, title):
        book = self._books.get(title.strip().lower())
        if book is None or book.copies == 0:
            raise NotAvailable(f"{title!r} is not on the shelf")
        book.copies -= 1

    def save(self, path):
        with open(path, "w", encoding="utf-8") as f:
            json.dump([asdict(b) for b in self._books.values()], f, indent=2)

    @classmethod
    def load(cls, path):
        lib = cls()
        with open(path, encoding="utf-8") as f:
            for d in json.load(f):
                lib._books[d["title"]] = Book(**d)
        return lib


lib = Library()
lib.add("Things Fall Apart", 2)
lib.lend("things fall apart ")
try:
    lib.lend("Unknown Book")
except LibraryError as e:
    print("sorry:", e)
lib.save("library.json")
print(Library.load("library.json")._books)

