assert s.units('ORS') == 12, 'a refused dispense must change nothing'
try:
    s.dispense('Insulin', 1)
    raise AssertionError('an unknown medicine should raise UnknownMedicine')
except UnknownMedicine:
    pass

s = Stock()
for args in [('ORS', 0, 30), ('ORS', -5, 30), ('ORS', 'ten', 30), ('ORS', 5), ('ORS', 5, -1), ('   ', 5, 1)]:
    try:
        s.add(*args)
        raise AssertionError('add%r should raise ValueError' % (args,))
    except ValueError:
        pass
assert len(s) == 0, 'refused adds must not add anything'
s.add('ORS', 5, 30)
for n in [0, -2]:
    try:
        s.dispense('ORS', n)
        raise AssertionError('dispense(ORS, %r) should raise ValueError' % n)
    except ValueError:
        pass
assert s.units('ORS') == 5

