"""Clinic medicine stock: Level 2 project."""
import json
from dataclasses import dataclass, asdict


class StockError(Exception):
    """Base class for every stock problem, so callers can catch them all at once."""


class UnknownMedicine(StockError):
    """The clinic doesn't stock that medicine."""


class OutOfStock(StockError):
    """Not enough units to give out."""


@dataclass
class Medicine:
    name: str
    units: int
    unit_price: float
    min_units: int = 10

    def value(self):
        return self.units * self.unit_price


class Stock:
    def __init__(self):
        self._items = {}            # name -> Medicine

    @staticmethod
    def _key(name):
        key = name.strip().lower()
        if not key:
            raise ValueError("a medicine needs a name")
        return key

    def add(self, name, units, unit_price=None):
        if not isinstance(units, int) or units <= 0:
            raise ValueError(f"units must be a whole number above 0, not {units!r}")
        key = self._key(name)
        if key in self._items:
            self._items[key].units += units
        else:
            if unit_price is None or unit_price < 0:
                raise ValueError(f"{key} is new: give a unit_price")
            self._items[key] = Medicine(key, units, unit_price)
        return self._items[key].units

    def units(self, name):
        med = self._items.get(self._key(name))
        return med.units if med else 0

    def dispense(self, name, units):
        key = self._key(name)
        if key not in self._items:
            raise UnknownMedicine(key)
        if not isinstance(units, int) or units <= 0:
            raise ValueError("units must be a whole number above 0")
        med = self._items[key]
        if units > med.units:
            raise OutOfStock(f"only {med.units} {key} left, asked for {units}")
        med.units -= units
        return med.units

    def low_stock(self):
        return sorted(k for k, med in self._items.items() if med.units < med.min_units)

    def total_value(self):
        return sum(med.value() for med in self._items.values())

    def __len__(self):
        return len(self._items)


# ---- my tests ----

def make():
    s = Stock()
    s.add("Paracetamol", 100, 5)
    s.add("ORS", 12, 30)
    return s


def test_add_and_units():
    s = make()
    assert s.units("paracetamol") == 100
    assert s.add("Paracetamol", 20) == 120
    assert len(s) == 2


def test_names_ignore_case_and_spaces():
    s = make()
    s.add("  PARACETAMOL ", 5)
    assert s.units("Paracetamol") == 105
    assert len(s) == 2


def test_dispense():
    s = make()
    assert s.dispense("ORS", 2) == 10
    assert s.units("ors") == 10


def test_out_of_stock_changes_nothing():
    s = make()
    try:
        s.dispense("ORS", 13)
    except OutOfStock:
        assert s.units("ORS") == 12
        return
    raise AssertionError("dispensing 13 of 12 should raise OutOfStock")


def test_unknown_medicine():
    s = make()
    try:
        s.dispense("Insulin", 1)
    except UnknownMedicine:
        return
    raise AssertionError("an unknown medicine should raise UnknownMedicine")


def test_low_stock_boundary():
    s = make()
    s.dispense("ORS", 2)                 # exactly 10 = min_units: not low yet
    assert s.low_stock() == []
    s.dispense("ORS", 1)                 # 9: low
    assert s.low_stock() == ["ors"]


def test_total_value():
    s = make()
    assert s.total_value() == 100 * 5 + 12 * 30

